-- ----------------------------------------------------------------------
-- Sanity check
-- ----------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM menu_category WHERE restaurant_id = 400070011) AS categories,
    (SELECT COUNT(*) FROM menu_item WHERE restaurant_id = 400070011) AS items,
    (SELECT COUNT(*) FROM menu_item_variant miv JOIN menu_item mi ON mi.menu_item_id=miv.menu_item_id WHERE mi.restaurant_id=400070011) AS variants,
    (SELECT COUNT(*) FROM menu_item_price mip JOIN menu_item_variant miv ON miv.variant_id=mip.variant_id JOIN menu_item mi ON mi.menu_item_id=miv.menu_item_id WHERE mi.restaurant_id=400070011 AND mip.service_mode_id=(SELECT service_mode_id FROM service_mode WHERE code='dine_in')) AS dine_in_prices,
    (SELECT COUNT(*) FROM menu_item_price mip JOIN menu_item_variant miv ON miv.variant_id=mip.variant_id JOIN menu_item mi ON mi.menu_item_id=miv.menu_item_id WHERE mi.restaurant_id=400070011 AND mip.service_mode_id=(SELECT service_mode_id FROM service_mode WHERE code='takeaway')) AS takeaway_prices,
    (SELECT COUNT(*) FROM menu_board_item WHERE restaurant_id=400070011 AND menu_board_id=400070011001) AS dining_board_items,
    (SELECT COUNT(*) FROM menu_board_item WHERE restaurant_id=400070011 AND menu_board_id=400070011002) AS takeaway_board_items,
    (SELECT COUNT(*) FROM menu_item WHERE restaurant_id=400070011 AND verification_status_code='needs_review') AS flagged_for_review;